import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class Element_siblingElements_TriageGen0Test {

    private Element parentElement;
    private Element sibling1;
    private Element sibling2;
    private Element targetElement;

    @Before
    public void setUp() {
        Attributes attributes = new Attributes();
        parentElement = new Element(Tag.valueOf("div"), "", attributes);
        sibling1 = new Element(Tag.valueOf("p"), "", attributes);
        sibling2 = new Element(Tag.valueOf("span"), "", attributes);

        parentElement.appendChild(sibling1);
        parentElement.appendChild(targetElement = new Element(Tag.valueOf("a"), "", attributes));
        parentElement.appendChild(sibling2);
    }

    @Test
    public void testSiblingElements_WithSiblings_ShouldReturnAll() {
        Elements siblings = targetElement.siblingElements();
        assertEquals(2, siblings.size());
        assertTrue(siblings.contains(sibling1));
        assertTrue(siblings.contains(sibling2));
    }












}

